theorem.raw:
\label{nonforkingextension}
Let $E\subseteq F\subseteq H$, $p\in S_n(E)$ $q\in S_n(F)$ and $\bv=(v_1,\dots,v_n)$, $\bw=(v_1,\dots,v_n)\in H^n$ be such that $p=tp(\bv/E)$ and $q=tp(\bw/F)$. Then $q$ is an extension of $p$ such that $\bw\ind^*_EF$ if and only if the following conditions hold:
    \begin{enumerate}
        \item For every $j=1,\dots,n$, $P_{acl(E)}(v_j)=P_{acl(F)}(w_j)$
        \item For every $j=1,\dots,n$, $(H_{P^\perp_{acl(E)}v_j},\p_{P^\perp_{acl(E)}v_j},P^\perp_{acl(E)}v_j)$ is isometrically isomorphic to $(H_{P^\perp_{acl(F)}w_j},\p_{P^\perp_{acl(F)}w_j},P^\perp_{acl(F)}w_j)$
    \end{enumerate}

\label{orthogonalityoverA}
Let $E\subseteq H$. Let $p,q\in
S_1(E)$, let $v$, $w\in H$ be such that $v\models p$ and $w\models q$. Then, $p\perp_E^a q$ if and only if $\f_{P^\perp_E(v_e)}\perp \f_{P^\perp_E(w_e)}$

lemma.raw:
\label{orthogonalityoverempty}
Let $p,q\in S_1(\emptyset)$, let $v$, $w\in H$ be such that $v\models p$ and $w\models q$.
Then, $p\perp^a q$ if and only if $\f_{v_e}\perp \f_{w_e}$.

\label{dominationoverempty}
Let $p,q\in S_1(\emptyset)$ and let $v$, $w\in H$ be such that $v\models p$ and $w\models q$.
Then, $p\vartriangleright_\emptyset q$ if and only if $\f_{w_e}\leq\f_{v_e}$.

